function mint(address usr, uint256 wad) external auth { dai[usr] = add(dai[usr], wad); supply = add(supply, wad); }
function burn(address usr, uint256 wad) external { dai[usr] = sub(dai[usr], wad); supply = sub(supply, wad); }
function transfer(address dst, uint256 wad) external returns (bool) { return transferFrom(msg.sender, dst, wad); }
